style.css:
@-moz-document domain("syosetu.com") {
/* Syosetu (Narou) Dark
     One frontend across the portal, the reader (ncode/novel18), yomou and mypage.
     Mostly hardcoded per element; a few :root tokens are remapped below. Colours
     only. */

  :root {
    color-scheme: dark !important;
    /* --color-ui-bg (#fff) is a background ONLY, so one remap covers every surface
       it paints. */
    --color-ui-bg: #14181d !important;
    --color-ui-bg--hover: #22272e !important;
    /* Hover-only washes. --color-bg-years-hover does triple duty on the アニメ化作品
       index — tile fill, flyout box-shadow, item hover. #21262d keeps
       --color-site-link on the tile at 4.6:1. */
    --color-bg--hover: #1c2128 !important;
    --color-bg-years-hover: #21262d !important;
    /* Every headline on the network paints from this one token, so the remap covers
       every consumer at once — incl. the aside bullet, which reads it as a
       background-color. The per-selector rules below cover legacy hardcoded hexes. */
    --color-text-headline: #e6c9a8 !important;
    --color-site-text-headline: #e6c9a8 !important;
    /* Nothing else reads these three, and they are the only cue separating a
       caution from a permission — keep them apart. */
    --color-bg-theme-default: #1c2128 !important;
    --color-bg-theme-danger: #2d1d1f !important;
    --color-bg-theme-success: #1b2519 !important;
    /* The bg token is a translucent black overlay that already reads dark; only the
       ink is wrong. */
    --color-faq-dt-text: #c4cdd6 !important;
    /* The step cards sit ON these slabs, so a slab is the elevated surface, not the
       base. The #22b8cf eyecatch hero is brand and stays. */
    --color-site-cheers-color-bg: #1c2128 !important;
    --color-site-partner-color-bg: #1c2128 !important;
    --color-site-partner-eyecatch-bg: #1c2128 !important;
    --color-site-partner-headline-bg: #21262d !important;
    --color-site-partner-notes-bg: #1c2128 !important;
  }

  /* ---- Base surfaces ---- */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Soften every default light border into a subtle dark divider */
  * {
    border-color: #262c33 !important;
  }

  /* ...but a border IS the affordance for these: the active tab's 3px underline
     (its ONLY active indicator), the checked radio/checkbox ring, and the panel
     body's cyan rules. */
  .c-horizontalnav__item.is-active {
    border-bottom-color: #5fb0e6 !important;
  }
  .c-form__radio-input:checked,
  .c-form__checkbox-input:checked {
    border-color: #58a6ff !important;
  }
  .c-panel__body {
    border-top-color: rgba(24, 183, 205, 0.5) !important;
    border-bottom-color: rgba(24, 183, 205, 0.5) !important;
  }

  /* Selected-state indicators
     Four markers, each defeated by a rule above: the period tabs' 4px underline
     and the heading accent border-left (border reset), the filter pill filled with
     --color-ui-bg (remapped to the page bg), the pager's brown current-page bar
     (2.1:1, under the 3:1 non-text floor) and the main-nav's WHITE active pill.
     Inactive siblings stay accent blue. */
  .c-tabnav-1st__current,
  .c-tabnav-2nd__current {
    color: #e6c9a8 !important;
    -webkit-text-fill-color: #e6c9a8 !important;
  }
  .c-tabnav-1st__current {
    border-bottom-color: #e6c9a8 !important;
  }
  .c-tabnav-2nd__current {
    background-color: #21262d !important;
  }
  .c-card-cluster-title,
  .c-application-cluster-title,
  .p-review-control__title {
    border-left-color: #e6c9a8 !important;
  }
  .c-pager__item.is-current::after {
    background-color: #5fb0e6 !important;
  }
  .p-main-nav__item.is-active > a {
    background-color: #4a2e1c !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  /* The CURRENT step is natively the darkest label in the row, an order that
     inverts on dark. The <span> carries its colour directly. */
  .c-stepnav__item span {
    color: #8b949e !important;
  }
  .c-stepnav__item--current span {
    color: #e6c9a8 !important;
  }

  /* Icon-font glyphs (::before / ::after `content:`)
     Visible symbols, not text nodes; each keeps a hardcoded legacy colour. The
     ユーザ登録 pill is the mirror case, light icon on orange. */
  .p-ranktop-nav__category-name::after,
  .series_search__series::before,
  #main_search .p-icon::before {
    color: #c4cdd6 !important;
  }
  .c-dropdown__icon::before {
    color: #9aa3ad !important;
  }
  /* --color-dropdown-bg-chips paints each bare <li>; the wrapper is transparent. */
  .c-dropdown__chips-group,
  .c-dropdown__chips-group li {
    background-color: #1c2128 !important;
  }
  /* The disc is painted from the WRAPPER's hover, so `.c-dropdown__icon:hover`
     alone never matches. */
  .c-dropdown:hover .c-dropdown__icon,
  .c-dropdown__icon:hover {
    background-color: #21262d !important;
  }
  .p-main-nav__item--useradd a,
  .p-main-nav__item--useradd .p-icon::before {
    color: #1a1109 !important;
  }
  /* The crown is a separate glyph from the number — give it the digits' medal
     tones. */
  .c-rank-place--1::before {
    color: #e3b341 !important;
  }
  .c-rank-place--2::before {
    color: #c9d1d9 !important;
  }
  .c-rank-place--3::before {
    color: #cd7f47 !important;
  }

  /* Generic light wrappers / panels -> elevated dark surface */
  .l-container,
  .l-main,
  .l-wrap,
  .l-jumbotron,
  .c-panel,
  .c-panel__body,
  .c-announce-box,
  .c-announce,
  .c-document,
  .searchkekka_box,
  .searchForm_box,
  .search_box,
  .index_box,
  .novel_bn,
  .p-footer-nav,
  .c-novel-attention,
  #novel_color,
  #container,
  #contents_main,
  #wrap {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* Card surfaces (ranking cards, recommendations, bookmark bar,
     feedback form) -> elevated dark, opaque */
  .c-card,
  .p-ranktop-item,
  .p-recommend,
  .p-recommend__item,
  .p-bookmark-bar,
  .c-novel-feedback-form,
  .p-bookmark-modal,
  .c-modal,
  .c-modal__item {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* Header / global navigation */
  /* The login / logout / password-reset pages carry no .p-header at all; this
     band is their header. */
  .p-header,
  .p-login-header,
  .l-header,
  .c-menu,
  .c-menu__body {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }

  .p-header__logo,
  .p-header__description,
  .p-header__description-data,
  .p-header__subnav-item,
  .p-header__subnav-item a {
    color: #c4cdd6 !important;
  }
  /* Pinned rather than left to the native token, which is brown #823f1c on
     yomou. */
  .p-header__count {
    color: #18b7cd !important;
  }

  /* One --color-ui-accent per site (brown on yomou, cyan elsewhere) cannot carry
     two hues, so the bar is unified on the Narou brown — the only place the
     network's accent hue is not preserved. */
  .p-main-nav,
  .p-sub-nav {
    background-color: #2a1a10 !important;
    border-color: #3a2517 !important;
  }

  .p-main-nav__item,
  .p-main-nav__item a,
  .p-main-nav__item-name,
  .p-sub-nav__item,
  .p-sub-nav__item a {
    color: #f0dccb !important;
  }

  .p-main-nav__item:hover,
  .p-main-nav__item a:hover {
    color: #ffffff !important;
  }

  /* "ユーザ登録" CTA pill — keep the brand orange, darken the label. */
  .p-main-nav__item--useradd,
  .p-main-nav__item--useradd .p-main-nav__item-name {
    color: #1a1109 !important;
  }

  /* The "more" scroll-fade is a ::after gradient fading to WHITE; remap the stop
     to the page base. */
  .c-horizontalnav__mask::after,
  .c-horizontalnav-button__mask::after {
    background-image: linear-gradient(to left, #14181d, rgba(20, 24, 29, 0)) !important;
  }

  /* Links & accents */
  a {
    color: #5fb0e6 !important;
  }
  a:hover {
    color: #9bd4ff !important;
  }

  /* Narou warm-orange title accent. Ranking titles come in three unrelated
     families, the last two a bare <a> — name each or it falls to the generic link
     blue. The wrapper forms cover markup with no anchor. */
  .novel_h a,
  .noveltitle a,
  .c-novel-item__title a,
  .p-ranktop-item__title,
  .p-ranktop-item__title a,
  .p-ranklist-item__title,
  .p-ranklist-item__title a {
    color: #f0954a !important;
  }
  .novel_h a:hover,
  .noveltitle a:hover,
  .c-novel-item__title a:hover,
  .p-ranktop-item__title a:hover,
  .p-ranklist-item__title a:hover {
    color: #ffb877 !important;
  }

  /* Only --login is natively red, so a blanket red would paint plain nav links in
     the danger hue. The sticky header stays opaque. */
  .c-menu__item,
  .c-menu__item--headnav,
  .c-menu__item--bookmark {
    background-color: #0d1117 !important;
    color: #c4cdd6 !important;
  }
  .c-menu__item a {
    color: #c4cdd6 !important;
  }
  .c-menu__item--login {
    color: #ff7b72 !important;
  }
  .c-menu__item--disabled {
    color: #6e7681 !important;
  }

  /* Reader — the novel chapter page (most important surface)
     Soft off-white body, comfortable headings, dim-but-legible metadata. */
  .p-novel,
  .p-novelmain,
  #novel_honbun,
  #novel_p,
  #novel_a {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* Never pure white (glare over long sessions). The text is bare <p>, so target
     the paragraphs and ruby <rt>/<rp> directly. */
  .p-novel__text,
  .js-novel-text,
  #novel_honbun,
  #novel_view,
  .novel_view,
  .p-novel__text p,
  .js-novel-text p,
  #novel_honbun p,
  #novel_view p,
  .novel_view p,
  .p-novel__text ruby,
  .p-novel__text rt,
  .p-novel__text rp,
  .js-novel-text rt,
  .js-novel-text rp {
    color: #c8d0d9 !important;
  }
  /* Furigana ruby annotations — slightly dimmer than the main line */
  .p-novel__text rt,
  .js-novel-text rt {
    color: #9aa3ad !important;
  }

  /* Chapter / story title */
  .p-novel__title,
  .p-novel__subtitle,
  .novel_subtitle,
  .c-title {
    color: #e6edf3 !important;
  }

  /* Episode number, dates, author line, update meta — muted but legible */
  .p-novel__number,
  .p-novel__author,
  .p-novel__date-published,
  .p-novel__date,
  .novel_writername,
  #novel_no,
  .koushinytime,
  .p-eplist__update,
  .c-pager__result-stats {
    color: #9aa3ad !important;
  }

  /* Story summary box */
  .p-novel__summary,
  #novel_ex {
    color: #b6c0ca !important;
  }

  /* Disclaimer/attention box — the hardcoded #dd0000 is illegible on dark. */
  .c-novel-attention__warning {
    color: #ff7b72 !important;
  }

  /* New-impressions / reader comments block (bottom of chapter). */
  .p-new-impression,
  .p-new-impression__list,
  .p-new-impression__item {
    background-color: transparent !important;
  }
  .p-new-impression__headline,
  .p-new-impression__text,
  .p-new-impression__name {
    color: #c4cdd6 !important;
  }

  /* The emoticon's fill IS the button affordance and its :hover shade the only
     press cue. */
  .p-reaction,
  .p-reaction__body {
    background-color: transparent !important;
  }
  .js-reactionepisode_change,
  .p-reaction__emoticon {
    background-color: #21262d !important;
  }
  .js-reactionepisode_change:hover,
  .p-reaction__emoticon:hover {
    background-color: #2d333b !important;
  }
  .p-reaction__count {
    color: #9bd4ff !important;
  }

  /* Novel comments / reviews (novelcom.syosetu.com)
     A newer family (.p-novelcom-* / .c-postedtext-*) with hardcoded light fills;
     darkened chips keep their light labels. */
  .c-postedtext--noposts,
  .p-novelcom-text,
  .p-novelcom-text--error {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .p-novelcom-text__caution,
  .u-text-attention {
    color: #ff7b72 !important;
  }
  /* Light-grey control chips: the 全て表示 filter button and the エピソードN badge. */
  .p-novelcom-header__narrowdown-button,
  .c-postedtext__target-info-episode {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* Posted impression/review meta; poster-name links stay accent blue. */
  .c-postedtext__poster,
  .c-postedtext__date,
  .c-postedtext__target-info {
    color: #9aa3ad !important;
  }
  .c-postedtext__poster a,
  .c-postedtext__target-info a {
    color: #5fb0e6 !important;
  }
  /* The one box in this family with a fill of its own; every sibling above is
     neutralized. */
  .c-postedtext__reply {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  /* Story index (TOC) — episode list */
  .p-eplist,
  .index_box {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .p-eplist__chapter-title,
  .chapter_title {
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .p-eplist__sublist,
  .p-eplist__subtitle a,
  .subtitle a {
    color: #5fb0e6 !important;
  }
  .p-eplist__subtitle a:hover,
  .subtitle a:hover {
    color: #9bd4ff !important;
  }
  /* An episode row has NO divider natively — its bottom border is its only state
     channel, which the blanket border reset flattens. Hover is last, so it still
     wins on a favourited row. */
  .p-eplist__sublist--underline {
    border-bottom-color: #e6c9a8 !important;
  }
  .p-eplist__sublist:hover {
    border-bottom-color: #5fb0e6 !important;
  }

  /* Pager / chapter prev-next navigation */
  .c-pager,
  .c-pager__pager {
    background-color: transparent !important;
  }
  .c-pager__item,
  .c-pager__item a,
  .novel_bn a {
    color: #5fb0e6 !important;
    border-color: #2d333b !important;
  }
  .c-pager__item a:hover,
  .novel_bn a:hover {
    color: #9bd4ff !important;
  }
  /* The rule above would make these disabled dead ends read as live links. */
  .c-pager__item.is-disabled,
  .c-pager__item.is-disabled a {
    color: #7d8590 !important;
  }
  /* Dead ends are marked a SECOND way here: 最初へ / 前へ ship as bare <span>, no
     class. The tag qualifier (0,2,1) beats `.c-pager__item` and leaves real <a>
     alone; the current page is a <span> too but has no direction modifier, so it
     keeps the blue label. */
  span.c-pager__item--first,
  span.c-pager__item--before,
  span.c-pager__item--next,
  span.c-pager__item--last {
    color: #7d8590 !important;
  }

  /* Sticky reader menu / layout-adjust (font-size) controls
     Must stay OPAQUE so chapter text never bleeds through. */
  .p-adjust-layout,
  .p-adjust-layout__controller,
  .p-adjust-layout__switch,
  .p-adjust-layout__list,
  .p-adjust-layout__list-item,
  .p-adjust-layout__bottom-close,
  .p-adjust-layout__illustration,
  .c-hover-nav,
  .c-hover-nav__list {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .p-adjust-layout__title,
  .p-adjust-layout__switch,
  .p-adjust-layout__switch span,
  .p-adjust-layout__bottom-close,
  .p-adjust-layout__controller span,
  .c-hover-nav__title {
    color: #c4cdd6 !important;
  }
  .p-adjust-layout__title {
    color: #e6edf3 !important;
  }
  /* The panel rule above colours the LIST, not the hovered item. */
  .c-hover-nav__item:hover {
    background-color: #2d333b !important;
  }
  /* A raster GIF of the whole button, so no colour rule reaches it; only the OFF
     state is a white pill. hue-rotate keeps its pale-blue edge blue, 0.92 lands
     the fill on the page base rather than black. */
  img.js-adjust-layout-illustflag[src*="novelview_off"] {
    filter: invert(0.92) hue-rotate(180deg);
  }
  /* The chips carry their own light fill, incl. the inner <span> that renders the
     label. */
  .js-adjust-layout-on,
  .js-adjust-layout-off,
  .p-adjust-layout__controller,
  .p-adjust-layout__switch span,
  .js-adjust-layout-on span,
  .js-adjust-layout-off span {
    background-color: #1c2128 !important;
  }

  /* Floating up/down navigater pills. */
  .c-navigater,
  .c-navigater--tobottom,
  .c-navigater--totop {
    background-color: #1c2128 !important;
    color: #9bd4ff !important;
    border-color: #2d333b !important;
    /* The `text-shadow: #fff 1px 1px 0` is a shadow, so no colour rule reaches it;
       on the dark chip it fringes the arrow white. */
    text-shadow: none !important;
  }
  .c-navigater a {
    color: #9bd4ff !important;
  }

  /* Font-size / layout radio + checkbox labels */
  .c-form__radio-label,
  .c-form__checkbox-label {
    color: #c4cdd6 !important;
  }
  /* appearance:none customs with a hardcoded #fff disc. The checked ::before
     keeps its accent dot, so selection still reads. */
  .c-form__radio-input,
  .c-form__checkbox-input {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  /* Bookmark (しおり) button, incl. the disabled modifier's own #fafafa fill. */
  .c-bookmark-button,
  .c-bookmark-button--disabled,
  .c-bookmark-button.c-bookmark-button--disabled {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .c-bookmark-button.c-bookmark-button--disabled {
    color: #9aa3ad !important;
  }

  /* Modal action buttons / toast close. */
  .c-button,
  .c-button--gray,
  .c-toast__close,
  .toaster_close {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* .c-button modifiers — the site's whole button semantics
     The bare .c-button is natively white, so the neutral chip above suits it; each
     modifier then carries a meaning that chip would flatten. Modifiers out-specify
     nothing, so they must come AFTER .c-button, and EVERY one is written
     `.c-button.c-button--x` (0,2,0), never bare (0,1,0): half render as <input>,
     and the generic input chip rule below is (0,1,1) and re-flattens a bare one. */
  .c-button.c-button--primary {
    background-color: #1f6feb !important;
    color: #ffffff !important;
    border-color: #1f6feb !important;
  }
  /* #1f6feb is already 4.6:1 under white, so lightening on hover would drop the
     label and its icon glyph to 3.3:1. */
  .c-button.c-button--primary:hover,
  .c-button.c-button--primary:focus,
  .c-button.c-button--primary:active {
    background-color: #1a5fd0 !important;
    color: #ffffff !important;
  }
  .c-button.c-button--delete {
    background-color: #da3633 !important;
    color: #ffffff !important;
    border-color: #da3633 !important;
  }
  /* Brand orange kept, label darkened — as on the nav's ユーザ登録 pill. */
  .c-button.c-button--useradd {
    background-color: #ff922b !important;
    color: #1a1109 !important;
    border-color: #ff922b !important;
  }
  /* Natively transparent link-buttons, not filled chips. */
  .c-button.c-button--minor,
  .c-button.c-button--outline,
  .c-button.c-button--secondary {
    background-color: transparent !important;
    color: #5fb0e6 !important;
  }
  /* blog.syosetu.com's scale is inverted: its BARE .c-button is the brand-blue
     primary and --secondary the quiet one. --center is emitted by the blog sheet
     alone, so it is the only hook that reaches the blog's primary without
     repainting the network's white bare button. */
  .c-button.c-button--center:not(.c-button--secondary) {
    background-color: #1f6feb !important;
    color: #ffffff !important;
    border-color: #1f6feb !important;
  }
  .c-button.c-button--center:not(.c-button--secondary):hover {
    background-color: #1a5fd0 !important;
    color: #ffffff !important;
  }
  /* Each is a transparent chip whose identity is its label colour: --outline-warn
     destructive, --outline-cheers the チアーズ green (paired with --primary-cheers'
     fill), --outline-none-active the disabled twin of --outline. */
  .c-button.c-button--outline-warn {
    background-color: transparent !important;
    color: #ff7b72 !important;
  }
  .c-button.c-button--outline-cheers {
    background-color: transparent !important;
    color: #3fbf95 !important;
  }
  .c-button.c-button--primary-cheers {
    background-color: #12b886 !important;
    color: #04231a !important;
    border-color: #12b886 !important;
  }
  .c-button.c-button--outline-none-active {
    background-color: transparent !important;
    color: #7d8590 !important;
  }
  /* The "already done" state (e.g. already favourited) — must read inactive */
  .c-button.c-button--none-active {
    background-color: #30363d !important;
    color: #8b949e !important;
    border-color: #30363d !important;
  }
  /* Natively a pale-yellow CTA, the site's "confirm" accent distinct from the
     blue --primary. As an <input type="submit"> it needs the qualified (0,2,0)
     form — see the block header. */
  .c-button.c-button--yellow {
    background-color: #d6a44a !important;
    color: #1a1109 !important;
