  #index_mnlt,
  #index_mid,
  #no_yes,
  .entrance_text,
  .entrance_text p {
    color: #c4cdd6 !important;
  }
  /* Every framed box here is fill-less — the coloured edge IS the box — and the
     border reset flattens them all. The desktop values are qualified with
     #index_contents, which exists only on the desktop gate. */
  #index_attention {
    border-color: #cc3399 !important;
  }
  #index_contents #index_attention {
    border-color: #cc99ff !important;
  }
  #entrance_in {
    border-top-color: #aa99ff !important;
    border-bottom-color: #aa99ff !important;
  }
  #index_mnlt {
    border-color: #3399cc !important;
  }
  #index_contents #index_mnlt {
    border-color: #66ccff !important;
  }
  #index_noc {
    border-color: #cc3399 !important;
  }
  #index_mid {
    border-color: #00dd99 !important;
  }
  /* The phone sheet paints these labels white at `#entrance a` (0,1,1), which our
     generic `a` rule wins on !important alone. Scoped by the phone-only ids so the
     desktop gate's bare links keep the accent blue. */
  #entrance a#no,
  #entrance a#yes,
  #entrance a#no span,
  #entrance a#yes span {
    color: #ffffff !important;
  }
  /* mnlt's base sheet's universal `* { color:#333 }` is a DIRECT match, beating
     anything the <a> above inherits down, so the caption under each entry link
     needs naming explicitly. */
  #index_right p.index_text {
    color: #9bd4ff !important;
  }
  p.index_attention,
  .free,
  .no_free {
    color: #9aa3ad !important;
  }
  /* The wordmark is a raster background, the entry links opaque white PNGs. An
     INSET box-shadow paints over the background but under the content, veiling the
     plate without restating the image URL — a re-declared background-image would
     land the moon logo on every other #container in the group. */
  div#container {
    box-shadow: inset 0 0 0 9999px rgba(20, 24, 29, 0.94) !important;
  }
  img[src*="mnlt_index_entrance_line"] {
    filter: invert(0.92) hue-rotate(180deg);
  }
  /* These wordmarks bake a #f3f3f3 plate into the pixels and their ink is PASTEL,
     so a partial invert leaves the plate visible; a full invert lands it within a
     few units of the #0d1117 header and hue-rotate restores both brand hues. */
  img[src*="mnlt_titlelogo"],
  img[src*="mnltk_logo"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Ad / PR slots: neutral dark so blank slots don't flash white */
  .c-ad,
  .c-ad__item-horizontal,
  .c-pr {
    background-color: transparent !important;
  }
  /* The ad DISCLOSURE must stay readable. Opaque so its native alpha cannot
     re-darken it against the page base. */
  .c-pr {
    color: #8b949e !important;
  }
  /* The close X is an inline SVG polygon with style="fill:#000;stroke:#000" — the
     ad's only dismiss control. The dark chip keeps it readable if a light creative
     loads behind it. The mobile sheet serves the same control under a DIFFERENT
     id. */
  /* Geniee serves the same dismiss; its own bg is transparent, so no chip —
     glyph only. */
  #flexible-sticky-ov-close-button,
  #flexible-sticky-wiped-button {
    background-color: #1c2128 !important;
  }
  #flexible-sticky-ov-close-button svg polygon,
  #flexible-sticky-ov-close-button svg path,
  #flexible-sticky-wiped-button svg polygon,
  #flexible-sticky-wiped-button svg path,
  #geniee_overlay_close svg polygon,
  #geniee_overlay_close svg path {
    fill: #c4cdd6 !important;
    stroke: #c4cdd6 !important;
  }

  /* なろうデベロッパー (dev.syosetu.com)
     A frontend of its own on a token set undefined everywhere else on the network,
     so remapping these at :root lands on dev alone. */
  :root {
    --color-gnav-bg: #0d1117 !important;
    --color-box-bg: #1c2128 !important;
    --color-code-bg: #21262d !important;
    --color-tips-bg: #16241f !important;
    --color-tips-inline-bg: #2b3138 !important;
    --color-site-tips: #16241f !important;
    /* the manuals' warning box paints its label AND its edge from this one */
    --color-site-notice: #ff7b72 !important;
  }
  /* That box is fill-less, so the edge IS the box, and the border reset crushes
     it ahead of the token. */
  .c-attention {
    border-color: #ff7b72 !important;
  }
  /* --color-site-base is consumed by the rest of the network too, so these cards
     take a selector, not a token remap. Their copy is declared on the anchor
     itself. */
  .p-index-nav__item a {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }
  /* The icon PNG's silhouette is drawn in the copy's own #343a40. Inverting
     restores the outline; hue-rotate keeps the gear on its brand hue instead of
     the complement. */
  .p-index-nav__item-icon img {
    filter: invert(1) hue-rotate(180deg);
  }
  /* A bare iframe document. `#narou` and `.novel_list` match zero elements
     anywhere else on the network. */
  #narou {
    background-color: #1c2128 !important;
    border-bottom-color: rgba(24, 183, 205, 0.5) !important;
  }
  /* A dev section heading is marked by a 2px cyan border-left and nothing else. */
  .c-title--md {
    border-left-color: #18b7cd !important;
  }

  /* Error / 404 page
     A solid #fff panel whose teal heading would go dark-on-dark once the panel
     darkens. */
  .p-error-panel {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }
  .p-error-panel__heading {
    color: #e6c9a8 !important;
  }
  .p-error-panel__support-text {
    color: #c4cdd6 !important;
  }

  /* Mobile (SP) frontend
     A separate stylesheet family for phone user agents reusing most desktop
     classes. These surfaces exist ONLY here; the two that ARE shared are remapped
     through their token instead (see the :root block at the end of this section). */
  /* The secondary menu row under the sticky header (--color-bg-menu-sp). */
  .c-menu__second {
    background-color: #161b22 !important;
  }
  /* Scroll-up-revealed, fixed at translateY(-45px) at rest. */
  .c-follow-header {
    background-color: #161b22 !important;
  }
  .c-follow-header__item {
    color: #9bd4ff !important;
  }
  /* login.gif is an OPAQUE raster of a key on white and cannot be recoloured. Pin
     every background component — the site's shorthand leaves background-size at
     `auto`, which would resolve against the SVG's 512 viewBox. */
  .c-menu__first-item--login::before {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 512 512'%3E%3Cpath fill='%235fb0e6' d='M336 352c97.2 0 176-78.8 176-176S433.2 0 336 0S160 78.8 160 176c0 18.7 2.9 36.8 8.3 53.7L7 391c-4.5 4.5-7 10.6-7 17v80c0 13.3 10.7 24 24 24h80c13.3 0 24-10.7 24-24v-40h40c13.3 0 24-10.7 24-24v-40h40c6.4 0 12.5-2.5 17-7l33.3-33.3c16.9 5.4 35 8.3 53.7 8.3zM376 96a40 40 0 1 1 0 80 40 40 0 0 1 0-80z'/%3E%3C/svg%3E") !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-size: 16px 16px !important;
  }
  /* A near-white band whose label inherits our body colour. */
  .c-novel-feedback-form__open-imp {
    background-color: #161b22 !important;
    color: #c4cdd6 !important;
  }
  /* The revealed form (`.c-novel-feedback-form__impform`, alias
     `.impression_form`) is a solid #fff panel with nothing inside declaring its
     own ink. The desktop form has neither class. */
  .c-novel-feedback-form__close-imp {
    background-color: #161b22 !important;
    color: #c4cdd6 !important;
  }
  .c-novel-feedback-form__impform,
  .impression_form {
    background-color: transparent !important;
  }
  /* The bookmark bar's 感想を書く chip is a pale-blue pill leaving its blue label
     at ~2:1. */
  .p-bookmark-bar__bkm-link--sp-honbun {
    background-color: #21262d !important;
    color: #9bd4ff !important;
  }
  /* Both are a solid brand-cyan strip with a link on them. */
  .p-drawer-nav__close a,
  .p-footer__pagetop a {
    background-color: #21262d !important;
    color: #9bd4ff !important;
  }
  /* A light bar; keep the Narou orange label, lifted for the dark chip. */
  .c-control__bar {
    background-color: #21262d !important;
    color: #f0954a !important;
  }
  /* The 履歴から検索 sibling is already the neutral chip via the generic button
     rule — match it. */
  .search_toggle.list_menu {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }
  h3.menu_list {
    background-color: #1c2128 !important;
    color: #e6c9a8 !important;
  }
  /* The phone builder nests a SECOND tier under each toggle that the desktop
     builder has no equivalent of, on yomou and all three R18 phone builders.
     `.genre_list.content-bg` keeps the elevated chip it gets above (0,2,0 beats
     the bare class). */
  .search_toggle.inside_menu {
    background-color: #161b22 !important;
    color: #c4cdd6 !important;
  }
  .content-bg {
    background-color: transparent !important;
  }
  .search-history_setting-note {
    background-color: #21262d !important;
  }
  /* #991da7 purple at 2.4:1; the mnlt-scoped rule further down does not reach
     the builder's own copies. */
  .content-head_h3 {
    color: #e6c9a8 !important;
  }
  /* A fourth result family, each part declaring the legacy #333 on itself, so
     the `#trad` lift above never reaches them. */
  #trad > .section,
  #trad > .page_bar {
    color: #c4cdd6 !important;
  }
  #trad > .section > p.bb {
    color: #e6c9a8 !important;
  }
  #trad > .page_bar b {
    color: #e6edf3 !important;
  }
  #trad > .attenstion_koushin,
  #accordion .accordion_head,
  #accordion .smpnovel_ex,
  #accordion .smpnovel_list p {
    color: #9aa3ad !important;
  }
  /* This CTA's fill is a `background:` gradient, so a background-COLOR override
     alone paints behind it. */
  #accordion .read_button {
    background: #21262d !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* These two classes are styled differently on desktop, so a plain selector
     would repaint the desktop one too. Both SP bands paint from a token no desktop
     rule consumes. */
  :root {
    --color-ui-c-drawer-headline-bg: #21262d !important;
    --color-adjust-layout-bg-title: #21262d !important;
  }

  /* Google Funding Choices consent dialog (.fc-consent-root)
     Rendered in the MAIN document on first visit; the blue CTA buttons keep their
     brand fill. */
  .fc-consent-root .fc-dialog,
  .fc-consent-root .fc-dialog-content,
  .fc-consent-root .fc-dialog-header,
  .fc-consent-root .fc-faq-contents,
  .fc-consent-root .fc-faq-icon,
  .fc-consent-root .fc-preference-container {
    background-color: #1c2128 !important;
  }
  .fc-consent-root .fc-dialog-headline,
  .fc-consent-root .fc-header-text,
  .fc-consent-root .fc-dialog p,
  .fc-consent-root .fc-dialog div,
  .fc-consent-root .fc-dialog span,
  .fc-consent-root .fc-dialog h1 {
    color: #c4cdd6 !important;
  }
  .fc-consent-root .fc-dialog a {
    color: #5fb0e6 !important;
  }
  /* The CMP ships its own !important rules at higher specificity, so the
     headline, the footer "List of partners" link and the FAQ disc must be matched
     selector-for-selector. */
  .fc-consent-root .fc-dialog .fc-header h1.fc-dialog-headline {
    color: #e6edf3 !important;
  }
  .fc-consent-root .fc-dialog .fc-footer a.fc-footer-link-v2,
  .fc-consent-root .fc-dialog .fc-footer a.fc-footer-link-v2:visited {
    color: #5fb0e6 !important;
  }
  .fc-consent-root .fc-faq-header .fc-faq-icon {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }
  .fc-consent-root .fc-faq-header .fc-faq-icon svg {
    fill: #c4cdd6 !important;
  }
  /* The CMP paints the FAQ list at 0,3,0 !important, so these qualify one level
     deeper through .fc-dialog. The bullet disc reads the token as a
     background-color and must move with its label. */
  .fc-consent-root .fc-dialog .fc-faq-contents .fc-faq-item,
  .fc-consent-root .fc-dialog .fc-faq-contents .fc-faq-consent-syncing,
  .fc-consent-root .fc-dialog .fc-faq-contents .fc-faq-item-title {
    color: #c4cdd6 !important;
  }
  .fc-consent-root .fc-dialog .fc-faq-contents .fc-faq-item-dot {
    background-color: #c4cdd6 !important;
  }
  /* The CMP's `?` and back-arrow glyphs are SVG paint, so no colour rule reaches
     them. */
  .fc-consent-root .fc-help-tip .fc-help-tip-icon svg,
  .fc-consent-root .fc-dialog-header .fc-dialog-header-back-button svg {
    fill: #c4cdd6 !important;
  }
  /* A hardcoded fill, not currentColor, so it must be lifted alongside its
     label. */
  .fc-consent-root .fc-launch-icon-svg svg {
    fill: #5fb0e6 !important;
  }
  /* A variant served on some visits instead of the full modal; the first-dialog
     rules key on .fc-dialog-header / .fc-cutout defaults and miss it. The CMP's
     rules here are 0,2,0 !important, so qualify one level deeper. */
  .fc-consent-root .fc-choice-dialog .fc-choice-dialog-header,
  .fc-consent-root .fc-close .fc-cutout-background {
    background-color: #1c2128 !important;
  }
  .fc-consent-root .fc-choice-dialog-header .fc-close svg {
    fill: #c4cdd6 !important;
  }
  /* The dialog's body copy is painted by the CMP's OWN !important rules at 0,3,0
     / 0,4,0, which out-specify the broad `.fc-dialog span/p/div` lift above —
     match each selector-for-selector. */
  .fc-consent-root .fc-dialog .fc-stacks .fc-stack-name,
  .fc-consent-root .fc-dialog .fc-header .fc-header-text,
  .fc-consent-root .fc-faq-header .fc-faq-label {
    color: #c4cdd6 !important;
  }
  .fc-consent-root .fc-dialog .fc-footer p {
    color: #9aa3ad !important;
  }
  /* The card body is already darkened above; only its white border leaks. */
  .fc-consent-root .fc-preference-container {
    border-color: #2d333b !important;
  }
  /* A deeper sub-surface the first-dialog rules never cover. Match at or above
     the CMP's own specificity — the h1 rule stays below the first dialog's 0,4,0
     headline rule, so that one keeps its brighter #e6edf3. */
  .fc-consent-root .fc-preferences-container .fc-preference-container .fc-preference-title h2,
  .fc-consent-root .fc-header h1,
  .fc-consent-root .fc-dialog .fc-header h1 {
    color: #c4cdd6 !important;
  }
  .fc-consent-root .fc-preference-container .fc-purpose-feature-description,
  .fc-consent-root .fc-preference-container .fc-preference-slider-label,
  .fc-consent-root .fc-dialog-content .fc-preference-container .fc-preference-description,
  .fc-consent-root .fc-dialog-content .fc-preference-container .fc-preference-description p,
  .fc-consent-root .fc-dialog-content .fc-preference-container .fc-preference-description li,
  .fc-consent-root .fc-dialog-content .fc-preference-container .fc-preference-description b,
  .fc-consent-root .fc-data-preferences-dialog .fc-body p {
    color: #9aa3ad !important;
  }
  /* The explainer sits in .fc-noneditable-body, outside the preference cards, so
     the card-scoped rule above misses it. */
  .fc-consent-root .fc-data-preferences-dialog .fc-noneditable-body p,
  .fc-consent-root .fc-data-preferences-dialog .fc-noneditable-body li {
    color: #9aa3ad !important;
  }
  /* "View details" links and the manage-vendors nav label are the CMP's dark
     #1967d2. */
  .fc-consent-root .fc-dialog-content .fc-preference-container .fc-preference-description a,
  .fc-consent-root .fc-navigation-button .fc-navigation-button-label {
    color: #5fb0e6 !important;
  }
  /* A bare white fill with black text; the primary Accept-all / Confirm-choices
     CTAs keep their brand fill. */
  .fc-consent-root .fc-data-preferences-dialog .fc-navigation-button {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .fc-consent-root .fc-footer-buttons-divider,
  .fc-consent-root .fc-preference-divider {
    background-color: #2d333b !important;
  }
  /* Its own CMP surface. Each vendor card's hairline is 0,3,0, out of reach of
     the divider names above, and its lead paragraph takes a #5f6368 the
     .fc-data-preferences-dialog copy above does not match. */
  .fc-consent-root .fc-preference-container .fc-preference-container-divider {
    background-color: #2d333b !important;
  }
  .fc-consent-root .fc-vendor-preferences-dialog .fc-body p {
    color: #9aa3ad !important;
  }
  /* Re-assert the label on the brand-blue CTAs (the broad text rule
     above would otherwise dim them). */
  .fc-consent-root .fc-button .fc-button-label {
    color: #ffffff !important;
  }
  /* Its own overlay layer, a sibling of .fc-dialog, so every rule above misses
     it. The CMP paints it at 0,2,0 / 0,3,1 !important, so each rule here goes one
     level deeper via .fc-help-dialog-container. */
  .fc-consent-root .fc-help-dialog-container .fc-help-dialog {
    background-color: #1c2128 !important;
  }
  .fc-consent-root .fc-help-dialog-container .fc-help-dialog h1 {
    color: #e6edf3 !important;
  }
  .fc-consent-root .fc-help-dialog-container .fc-help-dialog .fc-help-dialog-contents,
  .fc-consent-root .fc-help-dialog-container .fc-help-dialog .fc-help-dialog-contents div,
  .fc-consent-root .fc-help-dialog-container .fc-help-dialog .fc-help-dialog-contents li,
  .fc-consent-root .fc-help-dialog-container .fc-help-dialog .fc-help-dialog-contents p {
    color: #9aa3ad !important;
  }
  /* The CMP's #1967d2 at 0,3,0 !important — the bare `a` lift near the top of
     this block cannot reach it. */
  .fc-consent-root .fc-help-dialog-container .fc-help-dialog .fc-help-dialog-contents a {
    color: #5fb0e6 !important;
  }
  .fc-consent-root .fc-help-dialog-container .fc-help-dialog .fc-help-dialog-button-container {
    background-color: #21262d !important;
  }
  .fc-consent-root .fc-help-dialog-container .fc-help-dialog-close-button .fc-help-dialog-close-button-label {
    color: #5fb0e6 !important;
  }
  /* Hover cues on the footer-toned link families */
  /* These links already sit at the global hover blue, so `a:hover` cannot move
     them — and on ncode .l-foot-contents is the reader's whole post-chapter block,
     not just the footer. The .c-announce / .help-link rule (0,1,1) likewise ties
     a:hover and wins on source order. Specificity must reach 0,2,1 here. */
  .l-footer a:hover,
  .l-foot-contents a:hover,
  footer a:hover,
  .p-footer a:hover,
  .c-announce a:hover,
  .c-announce--note a:hover,
  .help-link:hover,
  div.c-under-nav .c-under-nav__item:hover,
  div.c-under-nav input.c-under-nav__pdflink:hover {
    color: #ffffff !important;
  }
  /* The floating ↓ / ↑ pill is natively a pale #cdd chip under the pointer. */
  .c-navigater:hover,
  .c-navigater a:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }
  /* Natively the useradd pill lightens and the outline chip re-inks on hover. */
  .c-button.c-button--useradd:hover {
    background-color: #ffa94d !important;
    border-color: #ffa94d !important;
  }
  .c-button.c-button--minor:hover,
  .c-button.c-button--outline:hover,
  .c-button.c-button--secondary:hover {
    background-color: #21262d !important;
    color: #9bd4ff !important;
  }

  /* A ranking row whose work was deleted or made private: the R18 sheets'
     `* { color:#333 }` reaches the rank-number span directly, so it cannot inherit
     the row's grey. */
  .deadlink,
  .deadlink_t,
  .deadlink .ranking_number_d {
    color: #9aa3ad !important;
  }
}
